const q = $input.first().json.query || {};
const expected = $env.WHATSAPP_VERIFY_TOKEN;
const ok = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === expected;
return [{ json: { ok, challenge: q['hub.challenge'] || '' } }];

// Parse the WhatsApp Cloud API webhook payload
const body = $input.first().json.body || $input.first().json;
let result = { isValidMessage: false };

try {
  const entry = body.entry?.[0];
  const change = entry?.changes?.[0];
  const value = change?.value;
  const message = value?.messages?.[0];
  const contact = value?.contacts?.[0];

  if (message && message.type === 'text') {
    result = {
      isValidMessage: true,
      phone: message.from,
      name: contact?.profile?.name || 'Customer',
      text: message.text.body,
      messageId: message.id,
      timestamp: message.timestamp
    };
  }
} catch (e) {
  result = { isValidMessage: false, error: e.message };
}

return [{ json: result }];

// Build or restore the per-customer conversation memory
const incoming = $('Parse Incoming Message').first().json;
let memory = {
  phone: incoming.phone,
  name: incoming.name,
  state: 'chatting',              // chatting | collecting_appointment | done
  history: [],
  pendingAppointment: {}
};

const binaryItem = $input.first();
if (binaryItem && binaryItem.binary && binaryItem.binary.data) {
  try {
    const buf = Buffer.from(binaryItem.binary.data.data, 'base64');
    const saved = JSON.parse(buf.toString('utf8'));
    memory = { ...memory, ...saved };
  } catch (e) {
    // no existing memory file yet - first-time customer, keep defaults
  }
}

memory.history.push({ role: 'customer', text: incoming.text, ts: incoming.timestamp });
// keep only the last 10 turns to control prompt size
memory.history = memory.history.slice(-10);

return [{ json: memory }];

