const memory = $('Parse / Init Memory').first().json;
let parsed = {
  intent: 'other',
  property_filters: {},
  faq_question: '',
  appointment_info: {},
  wants_visit: false
};

try {
  const raw = $input.first().json.response;
  parsed = { ...parsed, ...JSON.parse(raw) };
} catch (e) {
  // model returned non-JSON text - fall back to a generic chat intent
  parsed.intent = 'other';
}

return [{ json: { ...memory, understanding: parsed } }];

// Pulls together memory, extracted understanding, and reference data (properties/faqs)
// to decide what the bot should do next, and prepares the data block for the reply prompt.
const data = $input.first().json;
const understanding = data.understanding;
const properties = $('Properties CSV to JSON').all().map(i => i.json);
const faqs = $('FAQs CSV to JSON').all().map(i => i.json);

let action = 'general_chat';
let dataBlock = '';
let pendingAppointment = { ...data.pendingAppointment };
let state = data.state;

function norm(v) { return (v || '').toString().trim().toLowerCase(); }

if (data.state === 'collecting_appointment' || understanding.intent === 'provide_appointment_info' || understanding.wants_visit) {
  // merge any newly extracted fields into what we already have
  const info = understanding.appointment_info || {};
  for (const k of ['name','phone','email','preferred_date','preferred_time','property_id','property_title']) {
    if (info[k]) pendingAppointment[k] = info[k];
  }
  const required = ['name','phone','email','preferred_date','preferred_time'];
  const missing = required.filter(k => !pendingAppointment[k]);

  if (missing.length === 0) {
    action = 'appointment_complete';
    state = 'chatting';
  } else {
    action = 'collect_appointment_info';
    state = 'collecting_appointment';
    dataBlock = 'Still missing: ' + missing.join(', ');
  }
} else if (understanding.intent === 'property_search') {
  const f = understanding.property_filters || {};
  const matches = properties.filter(p => {
    if (norm(p['Status']) !== 'available') return false;
    if (f.city && norm(p['City']) !== norm(f.city)) return false;
    if (f.society && !norm(p['Society']).includes(norm(f.society))) return false;
    if (f.phase && !norm(p['Phase']).includes(norm(f.phase))) return false;
    if (f.property_type && !norm(p['Property Type']).includes(norm(f.property_type))) return false;
    if (f.size && !norm(p['Size']).includes(norm(f.size))) return false;
    return true;
  }).slice(0, 5);
  action = 'send_property_list';
  dataBlock = JSON.stringify(matches);
} else if (understanding.intent === 'faq') {
  const q = norm(understanding.faq_question || data.history[data.history.length - 1].text);
  let best = null, bestScore = 0;
  for (const f of faqs) {
    const words = norm(f['Question']).split(/\s+/);
    const score = words.filter(w => q.includes(w)).length;
    if (score > bestScore) { bestScore = score; best = f; }
  }
  action = 'send_faq_answer';
  dataBlock = best ? JSON.stringify(best) : 'No exact FAQ match found - answer generally and offer to connect the customer with an agent.';
} else if (understanding.intent === 'greeting') {
  action = 'greeting';
} else {
  action = 'general_chat';
}

return [{ json: { ...data, action, dataBlock, pendingAppointment, state } }];

