const ctx = $('Build Context & Decide Action').first().json;
let replyText = ($input.first().json.response || '').trim();
if (!replyText) {
  replyText = "Sorry, could you please repeat that? I want to make sure I get you the right information.";
}
ctx.history.push({ role: 'bot', text: replyText, ts: Date.now() });
ctx.history = ctx.history.slice(-10);
return [{ json: { ...ctx, replyText } }];

const ctx = $('Parse Reply').first().json;
const existing = $input.all().map(i => i.json);
const nextNum = existing.length + 1;
const apptId = 'APT-' + String(nextNum).padStart(5, '0');
const p = ctx.pendingAppointment;

const newRow = {
  'Appointment ID': apptId,
  'Date Created': new Date().toISOString().slice(0, 10),
  'Customer Name': p.name || '',
  'Phone': p.phone || ctx.phone,
  'Email': p.email || '',
  'Preferred Visit Date': p.preferred_date || '',
  'Preferred Time': p.preferred_time || '',
  'Property ID': p.property_id || '',
  'Property Title': p.property_title || '',
  'Status': 'Pending',
  'Agent Assigned': '',
  'Notes': ''
};

const allRows = [...existing, newRow];
return allRows.map(r => ({ json: r }));

const ctx = $('Parse Reply').first().json;
const rows = $('Append Appointment Row').all().map(i => i.json);
const last = rows[rows.length - 1];
return [{ json: { ...ctx, appointment: last } }];

